import functools
import time

def retry(max_attempts=3, delay=1):
    """
    A decorator that retries a function a specified number of times if it raises an exception.

    Args:
        max_attempts (int): The maximum number of times to attempt the function.
        delay (int): The time in seconds to wait between attempts.

    Returns:
        function: The decorated function.
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            attempts = 0
            while attempts < max_attempts:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    attempts += 1
                    if attempts == max_attempts:
                        print(f"Attempt {attempts} failed. Final exception: {e}")
                        raise e

                    print(f"Attempt {attempts} failed: {e}. Retrying in {delay}s...")
                    time.sleep(delay)
            return None
        return wrapper
    return decorator

# --- Demonstration ---

if __name__ == "__main__":
    # Example 1: A function that fails twice then succeeds
    counter = 0

    @retry(max_attempts=3, delay=1)
    def unstable_function():
        global counter
        counter += 1
        if counter < 3:
            raise ValueError("Temporary failure!")
        print("Success on attempt", counter)
        return "Function Result"

    print("Starting unstable_function test...")
    try:
        result = unstable_function()
        print(f"Final Result: {result}")
    except Exception as e:
        print(f"Caught final error: {e}")

    print("\n" + "-"*30 + "\n")

    # Example 2: A function that always fails
    @retry(max_attempts=3, delay=1)
    def permanent_failure():
        raise RuntimeError("Permanent failure!")

    print("Starting permanent_failure test...")
    try:
        permanent_failure()
    except Exception as e:
        print(f"Caught expected final error: {e}")
